  <script>
    // Carousel Interaction
    const track = document.getElementById('carouselTrack');
    const prevBtn = document.getElementById('prevBtn');
    const nextBtn = document.getElementById('nextBtn');

    if (prevBtn && nextBtn && track) {
      const scrollAmount = 300;

      prevBtn.addEventListener('click', () => {
        track.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
      });

      nextBtn.addEventListener('click', () => {
        track.scrollBy({ left: scrollAmount, behavior: 'smooth' });
      });
    }

    // Store Locator Interaction
    const searchBtn = document.getElementById('searchBtn');
    const storeResults = document.getElementById('storeResults');
    const zipInput = document.getElementById('zipInput');

    if (searchBtn && storeResults && zipInput) {
      searchBtn.addEventListener('click', () => {
        if (zipInput.value.trim() !== '') {
          storeResults.style.display = 'block';
        }
      });
      zipInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter' && zipInput.value.trim() !== '') {
          storeResults.style.display = 'block';
        }
      });
    }

    // Newsletter Signup Interaction
    const subscribeBtn = document.getElementById('subscribeBtn');
    const confirmationMsg = document.getElementById('confirmationMsg');
    const newsletterForm = document.getElementById('newsletterForm');
    const emailInput = document.getElementById('emailInput');

    if (subscribeBtn && confirmationMsg && emailInput) {
      subscribeBtn.addEventListener('click', () => {
        if (emailInput.value.trim() !== '') {
          newsletterForm.style.display = 'none';
          confirmationMsg.style.display = 'block';
        }
      });
    }
  </script>

